// Simulador de sensores virtuales — Smart Room Climate (Grupo 3)
// Genera un mensaje MQTT por habitación cada vez que el nodo inject dispara.
const PREFIJO = 'roomsenseg3';
const HABITACIONES = ['hab1', 'hab2', 'hab3'];

const r = (min, max) => Math.random() * (max - min) + min;
const lim = (v, min, max) => Math.min(max, Math.max(min, v));
// Codespaces trabaja en UTC: calculamos la hora local de Galicia
const hora = parseInt(new Date().toLocaleString('en-GB', { timeZone: 'Europe/Madrid', hour: '2-digit', hour12: false }));
const deDia = hora >= 8 && hora < 20;

const estado = context.get('estado') || {};

const msgs = HABITACIONES.map(h => {
    // Estado inicial de la habitación (solo la primera vez)
    const s = estado[h] || { temperatura: r(18, 22), humedad: r(40, 60), co2: r(450, 700) };

    // Evolución suave (random walk) para que los datos parezcan reales
    s.presencia   = Math.random() < 0.6;                                       // PIR
    s.temperatura = lim(s.temperatura + r(-0.2, 0.2), 15, 28);                 // SCD30
    s.humedad     = lim(s.humedad + r(-1, 1), 30, 80);                         // SCD30
    s.co2         = lim(s.co2 + (s.presencia ? r(5, 25) : r(-20, 0)), 400, 2000); // SCD30: sube con gente
    s.gas         = lim(s.gas + r(-5, 5), 50, 500);                            // sensor de gases
    s.luz         = Math.round(deDia ? r(300, 800) : r(0, 50));                // luz ambiental (lux)
    estado[h] = s;

    return {
        topic: `${PREFIJO}/${h}/sensores`,
        payload: {
            habitacion: h,
            timestamp: new Date().toISOString(),
            temperatura: +s.temperatura.toFixed(1),   // ºC
            humedad: +s.humedad.toFixed(1),           // %
            co2: Math.round(s.co2),                   // ppm
            luz: s.luz,                               // lux
            presencia: s.presencia,                   // PIR
            ventana_abierta: false,                   // sensor Hall
            modo: 'AUTO'                              // pulsador
        }
    };
});

context.set('estado', estado);
return [msgs];   // envía los N mensajes, uno tras otro, por la salida 1
